import crypto from 'node:crypto';

const secret = 'whsec_zealt_test_secret_key_5f2a9c';

async function runTests() {
  console.log('Starting Webhook Endpoint Tests...\n');

  // Test 1: Missing X-Signature-256 header
  {
    console.log('Test 1: Missing X-Signature-256 header');
    const response = await fetch('http://localhost:5173/webhook', {
      method: 'POST',
      body: JSON.stringify({ event: 'test', items: [] }),
    });
    console.log(`Status: ${response.status} (Expected: 401)`);
    console.log(`Body: ${await response.text()}\n`);
  }

  // Test 2: Invalid signature
  {
    console.log('Test 2: Invalid signature');
    const response = await fetch('http://localhost:5173/webhook', {
      method: 'POST',
      headers: {
        'X-Signature-256': 'sha256=invalidsignature1234567890abcdef1234567890abcdef1234567890abcdef',
      },
      body: JSON.stringify({ event: 'test', items: [] }),
    });
    console.log(`Status: ${response.status} (Expected: 401)`);
    console.log(`Body: ${await response.text()}\n`);
  }

  // Test 3: Valid signature but invalid JSON
  {
    console.log('Test 3: Valid signature but invalid JSON');
    const rawBody = '{invalid-json';
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(rawBody);
    const signature = 'sha256=' + hmac.digest('hex');

    const response = await fetch('http://localhost:5173/webhook', {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
      },
      body: rawBody,
    });
    console.log(`Status: ${response.status} (Expected: 400)`);
    console.log(`Body: ${await response.text()}\n`);
  }

  // Test 4: Valid signature, valid JSON, but invalid payload structure
  {
    console.log('Test 4: Valid signature, valid JSON, but invalid payload structure');
    const rawBody = JSON.stringify({ wrong: 'payload' });
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(rawBody);
    const signature = 'sha256=' + hmac.digest('hex');

    const response = await fetch('http://localhost:5173/webhook', {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
      },
      body: rawBody,
    });
    console.log(`Status: ${response.status} (Expected: 400)`);
    console.log(`Body: ${await response.text()}\n`);
  }

  // Test 5: Valid signature, valid JSON, valid payload structure
  {
    console.log('Test 5: Valid signature, valid JSON, valid payload structure');
    const rawBody = JSON.stringify({ event: 'order.created', items: ['item1', 'item2'] });
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(rawBody);
    const signature = 'sha256=' + hmac.digest('hex');

    const response = await fetch('http://localhost:5173/webhook', {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
        'Content-Type': 'application/json',
      },
      body: rawBody,
    });
    console.log(`Status: ${response.status} (Expected: 200)`);
    console.log(`Headers:`, Object.fromEntries(response.headers.entries()));
    console.log(`Body: ${await response.text()}\n`);
  }

  console.log('Tests completed.');
}

runTests().catch(console.error);

